def is_subsequence(w, s):
    i = 0
    for c in s:
        if i < len(w) and w[i] == c:
            i += 1
    return i == len(w)

def find_longest_word_brute(s, dictionary):
    best = ''
    for w in dictionary:
        if is_subsequence(w, s):
            if len(w) > len(best) or (len(w) == len(best) and w < best):    # compare each candidate directly
                best = w
    return best

