import java.util.*;

public class Main {
    static String findLongestWord(String s, List<String> dictionary) {
        dictionary.sort((a, b) -> a.length() != b.length() ? b.length() - a.length() : a.compareTo(b));  // sort by length desc, then lex asc
        for (String w : dictionary) {
            if (isSubsequence(w, s)) return w;                       // first match is the final answer
        }
        return "";
    }

    static boolean isSubsequence(String w, String s) {
        int i = 0;
        for (char c : s.toCharArray()) {
            if (i < w.length() && w.charAt(i) == c) i++;
        }
        return i == w.length();
    }
}

