#include <bits/stdc++.h>
using namespace std;

bool isSubsequence(const string& w, const string& s) {
    size_t i = 0;
    for (char c : s) {
        if (i < w.size() && w[i] == c) i++;
    }
    return i == w.size();
}

string findLongestWord(string s, vector<string>& dictionary) {
    sort(dictionary.begin(), dictionary.end(), [](const string& a, const string& b) {
        if (a.size() != b.size()) return a.size() > b.size();          // longer first
        return a < b;                                                    // then lex smaller first
    });
    for (auto& w : dictionary) {
        if (isSubsequence(w, s)) return w;                                // first match is the final answer
    }
    return "";
}
